#!/usr/bin/env bash
set -euo pipefail
cd "$HOME/PFMP" || exit 1

DEPLOYMENT_ID="AKfycby6ykCxTxhUjq8FeKoBzgEMj6xzdrjXnBFgOt-1pAw1GfkaAigWMH7jj0EIg_BWpEkmxg"
LABEL="PFMP v1.0.0-dev.148"
SERVICE="apps-script/EUC_CONVENTION_PFMP_AdminWorkflowV144.gs"
PAGE="apps-script/Admin_Conventions_PFMP.html"

STAMP="$(date +%Y%m%d_%H%M%S)"
BACKUP="backup_avant_DEV148_${STAMP}"
mkdir -p "$BACKUP"
cp "$SERVICE" "$BACKUP/"
cp "$PAGE" "$BACKUP/"

echo "" | base64 -d > /tmp/dev148_patch.py
python3 /tmp/dev148_patch.py

echo "============================================================"
echo " DEV.148 — CONTROLES"
echo "============================================================"

cp "$SERVICE" /tmp/EUC_ADMIN_WORKFLOW_V148.js
node --check /tmp/EUC_ADMIN_WORKFLOW_V148.js

grep -q "EUC_PFMP_contexteAnneeV148" "$SERVICE"
grep -q "EUC_PFMP_definirAnneeActiveV148" "$SERVICE"
grep -q "EUC_ADMIN_WORKFLOW_listerDossiersParAnneeV148" "$SERVICE"
grep -q 'id="schoolYearSelect"' "$PAGE"
grep -q "const ANNEE_CTX=" "$PAGE"

python3 - <<'PY'
from pathlib import Path
import re
s=Path("apps-script/Admin_Conventions_PFMP.html").read_text(encoding="utf-8")
scripts=re.findall(r"<script>(.*?)</script>",s,re.S)
js="\n".join(scripts)
js=re.sub(r"<\?!=.*?\?>","{}",js)
Path("/tmp/Admin_Conventions_PFMP_DEV148.js").write_text(js,encoding="utf-8")
PY

node --check /tmp/Admin_Conventions_PFMP_DEV148.js

echo "OK : services année scolaire présents."
echo "OK : sélecteur année scolaire présent."
echo "OK : JavaScript client valide."

echo
echo "=== PUSH ==="
clasp push -f

echo
echo "=== VERSION ==="
clasp version "$LABEL"

echo
echo "=== DEPLOIEMENT PRINCIPAL ==="
clasp deploy -i "$DEPLOYMENT_ID" -d "$LABEL"

echo
echo "============================================================"
echo " DEV.148 DEPLOYEE AVEC SUCCES"
echo "============================================================"
echo "✓ contexte année scolaire centralisé"
echo "✓ année active mémorisée par utilisateur"
echo "✓ sélection automatique de l'année courante"
echo "✓ conventions filtrées par année scolaire"
echo "✓ recherche limitée à l'année active"
echo "✓ push + version + déploiement principal"
echo "============================================================"
